"""Contact matching: the workflow as a program. Generated by Agent Workflow Studio from the published
release; export again rather than edit (the steps it calls are in core/, unchanged from the studio)."""

from pathlib import Path

from .core import runner, steps  # noqa: F401

HERE = Path(__file__).parent
TITLE, VERSION = 'Contact matching', '1.0.0'
PURPOSE = ('Give every contact one entity id: contacts of the same person or company share it, and uncertain '
 'pairs go to you.')
# The workflow's App inputs: name -> [default, type, description].
INPUTS = {'exports': ['sample',
             'COMBO',
             'The folder with your contact exports (contacts, phones and addresses CSV files).'],
 'columns': ['# Which column holds what. Files are in the data folder. Only key, birth_date and '
             'one name\n'
             '# column are required; leave out what your data does not have.\n'
             'key: CONT_ID                      # or a list of columns that together identify a '
             'contact\n'
             'contacts: contacts.csv\n'
             'surname: {kanji: LAST_NAME_KANJI, kana: LAST_NAME_KANA, romaji: LAST_NAME_ROMAJI}\n'
             'given: {kanji: FIRST_NAME_KANJI, kana: FIRST_NAME_KANA, romaji: FIRST_NAME_ROMAJI}\n'
             'birth_date: BIRTH_DATE            # or {column: 生年月日, format: "%Y/%m/%d"}\n'
             'gender: GENDER\n'
             'type: {column: CONT_TYPE, company: ["2"]}   # the values that mean a company\n'
             'phones: {file: phones.csv, columns: [PHONE]}          # no file: columns of the '
             'contacts file\n'
             'addresses: {file: addresses.csv, kanji: [ADDRESS_KANJI]}  # several columns: parts '
             'of one address\n',
             'STRING',
             'The column map: which column of your exports holds the key, names, birth date, '
             'phones and addresses.'],
 'batch': [50, 'INT', 'How many pairs to ask you about each run.'],
 'match_at': [0.5,
              'FLOAT',
              'Merge pairs at least this likely to be the same (raise it for fewer wrong merges).'],
 'review_from': [0.1, 'FLOAT', 'Pairs from here up to Match at go to your review queue.'],
 'corroboration': [False,
                   'BOOLEAN',
                   'A merge also needs a shared phone, house, town or alias, not only name and '
                   'birth date.'],
 'max_size': [12, 'INT', 'The most contacts one entity may have.']}
OUTPUTS = ['entities', 'review_queue']
FOLDERS = ['exports']  # inputs that name a data folder
EXAMPLES = [{'id': 'E1',
  'given': {'exports': '@examples/E1/sample'},
  'expect': {'entities': 'EX01 EX01, EX02 EX01, EX03 EX03, EX04 EX03, EX05 EX05, EX06 EX06, EX07 '
                         'EX07, EX08 EX08, EX09 EX09, EX10 EX10'},
  'note': 'Day 0, no reviews: EX01/02 and EX03/04 merge; a family (EX05/06) and namesakes '
          '(EX09/10) stay apart. The company pair EX07/08 merges once reviews teach the model.'}]


def run(out, labels=None, **given):
    """Run the workflow; `given` overrides any input. Returns the runtime (checks, outputs, lines)."""
    values = {k: (given[k] if given.get(k) is not None else d) for k, (d, _, _) in INPUTS.items()}
    input_dir = Path(out)
    for name in FOLDERS:
        folder = Path(str(values[name]).replace("@examples", str(HERE / "examples"), 1)).resolve()
        if not folder.is_dir():
            raise SystemExit(f"No folder {folder} for --{name.replace('_', '-')}.")
        input_dir, values[name] = folder.parent, folder.name
    rt = runner.Runtime(Path(out), input_dir, labels)
    n1 = runner.data_folder(rt.ctx('data_folder'), folder=values['exports'])  # Input · exports
    n12_2 = steps.read_contacts(rt.ctx('read_contacts'), folder=n1[0], columns=values['columns'])  # Read contacts
    n12_13 = runner.check(rt.ctx('check'), kind='rows_at_least', expect='1', says='The exports are read: at least one contact (10,540 on the benchmark data).', value=n12_2[0])  # Check · contacts
    n14_3 = steps.standardize_contacts(rt.ctx('standardize_contacts'), towns=str(HERE / "reference" / 'towns.tsv'), kana_ocr=True, readings=True, split_one_field=True, shop_alias=True, company_clean=True, contacts=n12_2[0])  # Standardize contacts
    n14_15 = runner.check(rt.ctx('check'), kind='rows_at_least', expect='1', says='Every contact read is standardized.', value=n14_3[0])  # Check · records
    n16_4 = steps.find_contact_candidates(rt.ctx('find_contact_candidates'), exact=True, shared=True, locality=True, similar=True, exact_cap=50, shared_cap=20, similarity=0.5, records=n14_3[0])  # Find contact candidates
    n16_17 = runner.check(rt.ctx('check'), kind='rows_at_least', expect='1', says='Candidate pairs are found (15,219 on the benchmark data).', value=n16_4[0])  # Check · candidates
    n18_5 = steps.compare_contacts(rt.ctx('compare_contacts'), records=n14_3[0], candidates=n16_4[0])  # Compare contacts
    n18_19 = runner.check(rt.ctx('check'), kind='rows_at_least', expect='1', says='Every candidate pair is compared.', value=n18_5[0])  # Check · pairs
    n20_6 = steps.learn_from_reviews(rt.ctx('learn_from_reviews'), batch=values['batch'], audit=True, answer_key_file='', budget=1000, seed=0, pairs=n18_5[0])  # Learn from your reviews
    n20_21 = runner.check(rt.ctx('check'), kind='rows_at_least', expect='1', says='Every compared pair gets a score.', value=n20_6[0])  # Check · scored
    n22_7 = steps.decide_pairs(rt.ctx('decide_pairs'), match_at=values['match_at'], review_from=values['review_from'], corroboration=values['corroboration'], pairs=n20_6[0])  # Decide by score
    n11 = runner.api_output(rt.ctx('api_output'), name='review_queue', value=n22_7[1])  # Output · review_queue
    n22_23 = runner.check(rt.ctx('check'), kind='rows_at_least', expect='1', says='Every scored pair is decided.', value=n22_7[0])  # Check · decisions
    n24_8 = steps.cluster_guard(rt.ctx('cluster_guard'), max_size=values['max_size'], scores_separate=True, data=n22_7[0])  # Group into entities (guarded)
    n24_25 = runner.check(rt.ctx('check'), kind='rows_at_least', expect='1', says='The decided pairs are grouped.', value=n24_8[0])  # Check · clusters
    n26_9 = steps.entity_per_contact(rt.ctx('entity_per_contact'), records=n12_2[0], clusters=n24_8[0])  # Entity per contact
    n10 = runner.api_output(rt.ctx('api_output'), name='entities', value=n26_9[0])  # Output · entities
    n26_27 = runner.check(rt.ctx('check'), kind='rows_at_least', expect='1', says='Every contact gets an entity id.', value=n26_9[0])  # Check · entities
    return rt
